<x-app-layout><x-slot name="header"><h1 class="text-xl font-bold">Transfer Add</h1></x-slot><form method="POST" action="{{route('item-transfers.store')}}" x-data="tf()">@csrf<section class="rounded border bg-white p-6"><h2 class="border-b pb-3 text-lg">General Info</h2><div class="mt-4 grid gap-4 md:grid-cols-2"><label>Transfer Date<input name="transfer_date" type="date" value="{{now()->format('Y-m-d')}}" class="mt-2 w-full rounded border"></label><label>Transfer No<input readonly value="{{$nextNo}}" class="mt-2 w-full rounded border bg-slate-100"></label><label>Transfer Type<select name="transfer_type" class="mt-2 w-full rounded border"><option value="store">Store</option></select></label><label>Remarks<input name="remarks" class="mt-2 w-full rounded border"></label><label>Store From<select name="from_store_id" x-model="from" required class="mt-2 w-full rounded border"><option value="">[Select]</option>@foreach($stores as $s)<option value="{{$s->id}}">{{$s->name}}</option>@endforeach</select></label><label>Store To<select name="to_store_id" x-model="to" required class="mt-2 w-full rounded border"><option value="">[Select]</option>@foreach($stores as $s)<option value="{{$s->id}}">{{$s->name}}</option>@endforeach</select></label></div></section><section class="mt-5 overflow-hidden rounded border border-sky-200 bg-white"><div class="bg-sky-500 px-4 py-2 text-white">Parts Line</div><div class="overflow-x-auto"><table class="w-full min-w-[800px] text-sm"><thead class="bg-sky-50"><tr><th>Item No</th><th>Item</th><th>Position From</th><th>Position To</th><th>Qty</th><th></th></tr></thead><tbody><template x-for="(l,i) in lines"><tr class="border-t"><td><input x-model="l.part" @input="match(l)" :list="`p-${i}`" class="w-full border"><datalist :id="`p-${i}`"><template x-for="p in products"><option :value="p.part_no" x-text="`${p.part_no} — ${p.name}`"></option></template></datalist><input type="hidden" :name="`items[${i}][product_id]`" x-model="l.product"><input type="hidden" :name="`items[${i}][unit_cost]`" x-model="l.cost"></td><td><input x-model="l.name" readonly class="w-full border bg-slate-50"></td><td><select :name="`items[${i}][from_position_id]`" class="w-full border"><option value="">[Select]</option><template x-for="p in positions.filter(x=>String(x.store_id)==String(from))"><option :value="p.id" x-text="p.name"></option></template></select></td><td><select :name="`items[${i}][to_position_id]`" class="w-full border"><option value="">[Select]</option><template x-for="p in positions.filter(x=>String(x.store_id)==String(to))"><option :value="p.id" x-text="p.name"></option></template></select></td><td><input x-model.number="l.qty" :name="`items[${i}][quantity]`" type="number" min=".01" step=".01" class="w-full border"></td><td><button type="button" @click="del(i)" x-show="lines.length>1">×</button></td></tr></template></tbody></table></div><button type="button" @click="add" class="m-3 rounded bg-sky-100 px-3 py-2">+ Add row</button></section><div class="mt-3 flex justify-between"><span>Total Qty: <b x-text="lines.reduce((a,x)=>a+(+x.qty||0),0)"></b></span><span>Total Amount: ৳<b x-text="lines.reduce((a,x)=>a+(+x.qty||0)*(+x.cost||0),0).toFixed(2)"></b></span></div><div class="mt-5"><button class="rounded bg-[#1f7d88] px-5 py-2 text-white">Save</button></div></form><script>function tf(){return{products:@json($products),positions:@json($positions),from:'',to:'',lines:[{part:'',product:'',name:'',cost:0,qty:0}],add(){this.lines.push({part:'',product:'',name:'',cost:0,qty:0})},del(i){this.lines.splice(i,1)},match(l){let p=this.products.find(x=>x.part_no?.toLowerCase()===l.part.toLowerCase()||`${x.part_no} — ${x.name}`.toLowerCase()===l.part.toLowerCase());if(p)Object.assign(l,{part:p.part_no,product:p.id,name:p.name,cost:p.unit_price});else Object.assign(l,{product:'',name:'',cost:0})}}}</script></x-app-layout>
